'use strict';
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.ReikaChat=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
const MAX_TEXT=500,MAX_HISTORY=40;
function clean(s){return String(s??'').trim().slice(0,MAX_TEXT);}
function respond(text){const q=clean(text).toLowerCase();if(/привет|здравствуй|добрый/.test(q))return 'Привет! Я Рэйка Куроноцуки. Рада тебя видеть.';if(/как дела|как ты/.test(q))return 'Спасибо, всё спокойно. Девять хвостов сегодня особенно пушистые!';if(/кто ты|твоё имя|твое имя/.test(q))return 'Я Рэйка — девятихвостая кицунэ, пока живущая в этом локальном прототипе.';if(/помощ|что умеешь/.test(q))return 'Сейчас я могу отвечать на простые фразы, менять настроение и произносить текст через браузер.';return 'Я услышала тебя. Пока мои ответы работают по локальным правилам, без подключения к нейросети.';}
function createStore(){let entries=[];return {get all(){return entries.map(x=>({...x}));},add(role,text){if(!['user','reika'].includes(role))throw new TypeError('Invalid role');const value=clean(text);if(!value)return false;entries.push({role,text:value});entries=entries.slice(-MAX_HISTORY);return true;},clear(){entries=[];}};}
function mount(){const panel=document.querySelector('.panel');if(!panel)return;const section=document.createElement('section');section.className='reika-chat';section.innerHTML='<h3>Чат с Рэйкой · офлайн</h3><div id="chatHistory" role="log" aria-live="polite"></div><label for="chatInput">Сообщение</label><textarea id="chatInput" rows="2" maxlength="500" placeholder="Скажи привет Рэйке"></textarea><div class="speech-actions"><button id="chatSend" type="button">Отправить</button><button id="chatSpeak" type="button">Озвучить ответ</button><button id="chatClear" type="button">Очистить историю</button></div><p id="chatStatus" role="status">Локальные ответы без AI-сервера; история хранится только в этой вкладке.</p>';panel.append(section);
const store=createStore(),log=section.querySelector('#chatHistory'),field=section.querySelector('#chatInput'),status=section.querySelector('#chatStatus');let lastReply='';
function render(){log.replaceChildren();for(const item of store.all){const line=document.createElement('p');line.className='chat-line';const who=document.createElement('strong');who.textContent=item.role==='user'?'Вы: ':'Рэйка: ';line.append(who,document.createTextNode(item.text));log.append(line);}log.scrollTop=log.scrollHeight;}
function send(){const text=clean(field.value);if(!text){status.textContent='Введите сообщение.';return;}store.add('user',text);lastReply=respond(text);store.add('reika',lastReply);field.value='';render();status.textContent='Ответ сформирован локально.';window.dispatchEvent(new CustomEvent('reika:reply',{detail:{text:lastReply}}));}
section.querySelector('#chatSend').addEventListener('click',send);field.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send();}});
section.querySelector('#chatClear').addEventListener('click',()=>{store.clear();lastReply='';render();status.textContent='История очищена.';});
section.querySelector('#chatSpeak').addEventListener('click',()=>{if(!lastReply){status.textContent='Сначала получите ответ Рэйки.';return;}const speechInput=document.querySelector('#speechText'),speechButton=document.querySelector('#speechPlay');if(!speechInput||!speechButton||speechButton.disabled){status.textContent='Озвучка недоступна.';return;}speechInput.value=lastReply;speechButton.click();status.textContent='Ответ передан озвучке.';});
return store;}
return {MAX_TEXT,MAX_HISTORY,clean,respond,createStore,mount};
});
if(typeof window!=='undefined')window.ReikaChatStore=window.ReikaChat.mount();
